const fs = require('fs');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const https = require('https');

function get(path) {
  return new Promise((resolve) => {
    const req = https.request({ hostname: 'api.ivxholding.com', path, method: 'GET', headers: { 'Authorization': 'Bearer ' + TOKEN, 'Accept': 'application/json' }, timeout: 30000 }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => { try { resolve({status: res.statusCode, body: JSON.parse(data)}); } catch(e) { resolve({status: res.statusCode, raw: data.slice(0,3000)}); } });
    });
    req.on('error', err => resolve({error: err.message}));
    req.on('timeout', () => { req.destroy(); resolve({error: 'timeout'}); });
    req.end();
  });
}

(async () => {
